import socket
host = "dppmsserchhip.mizoram.gov.in"
try:
    infos = socket.getaddrinfo(host, 443, proto=socket.IPPROTO_TCP)
    ips = sorted({i[4][0] for i in infos})
    print("Resolved IPs:", ips)
    for ip in ips:
        try:
            print("PTR", ip, "->", socket.gethostbyaddr(ip)[0])
        except Exception as e:
            print("PTR", ip, "-> none:", type(e).__name__)
except Exception as e:
